<section id="messages" class="screen">
    <div class="screen-head left">
        <p class="tiny-label">COMMUNICATION</p>
        <h2>MESSAGES & <span>CONNECTIONS</span></h2>
        <p>Keep conversations with clients and collaborators in one place.</p>
    </div><div class="message-filters" role="tablist" aria-label="Filter conversations"><button class="message-filter active" data-message-filter="all" type="button">All</button><button class="message-filter" data-message-filter="unread" type="button">Unread</button></div><div class="messages-layout">
        <div class="conversation-list">
            <div class="conversation-list-head">
                <h3>Inbox</h3><input id="messageSearch" type="search" placeholder="Search conversations" aria-label="Search conversations"></div><div id="conversationList">
                    
                </div></div><div class="chat-window"><div class="chat-head"><h3 id="chatName">Select a conversation</h3><p id="chatSub">Your messages appear here.</p></div><div class="chat-messages" id="chatMessages"><p class="empty-chat">Choose a conversation to read your messages.</p></div><form class="chat-form" id="chatForm"><input id="chatInput" placeholder="Write a message..." autocomplete="off" maxlength="2000" disabled><button class="pill-btn pill-orange" type="submit" disabled>Send</button></form></div></div></section>
